// exportAirflowSettings exports the running Airflow objects to either a settings file or an env file
func (d *DockerCompose) exportAirflowSettings(containerID, settingsFile, envFile string, airflowDockerVersion uint64, connections, variables, pools, envExport, logs bool) error {
	if envExport {
		if err := envExportSettings(containerID, envFile, airflowDockerVersion, connections, variables, logs); err != nil {
			return err
		}
		fmt.Println("\nAirflow objects exported to env file")
		return nil
	}
	if err := exportSettings(containerID, settingsFile, airflowDockerVersion, connections, variables, pools, logs); err != nil {
		return err
	}
	fmt.Println("\nAirflow objects exported to settings file")
	return nil
}

// importAirflowSettings creates Airflow objects in the running project from a settings file
func (d *DockerCompose) importAirflowSettings(containerID, settingsFile string, airflowDockerVersion uint64, connections, variables, pools, logs bool) error {
	if err := initSettings(containerID, settingsFile, airflowDockerVersion, connections, variables, pools, logs); err != nil {
		return err
	}
	fmt.Println("\nAirflow objects created from settings file")
	return nil
}

